package com.primehr.learningdevelopment.delivery.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.LocalDate;
@Entity@Table(name="ld_consolidated_plan_source",uniqueConstraints=@UniqueConstraint(name="uk_ld_plan_source",columnNames={"agency_id","plan_id","source_type","source_id"}))
public class LdConsolidatedPlanSource extends RspAuditedEntity{
 public enum SourceType{APPROVED_IDP_ITEM,ORGANIZATIONAL_NEED}
 @Column(name="plan_id",nullable=false,length=36)private String planId;@Enumerated(EnumType.STRING)@Column(name="source_type",nullable=false,length=30)private SourceType sourceType;@Column(name="source_id",nullable=false,length=36)private String sourceId;@Column(name="source_version",nullable=false)private long sourceVersion;@Column(name="source_fingerprint",nullable=false,length=64)private String sourceFingerprint;@Column(name="employee_no",length=100)private String employeeNo;@Column(name="organization_id",nullable=false)private Long organizationId;@Column(name="organization_name",nullable=false,length=200)private String organizationName;@Column(name="development_objective",nullable=false,length=3000)private String developmentObjective;@Column(name="success_measure",nullable=false,length=2000)private String successMeasure;@Column(name="target_date")private LocalDate targetDate;@Column(nullable=false,length=20)private String priority;@Column(name="display_order",nullable=false)private int displayOrder;
 protected LdConsolidatedPlanSource(){}public LdConsolidatedPlanSource(String agency,String plan,SourceType type,String source,long version,String fingerprint,String employeeNo,Long organizationId,String organizationName,String objective,String measure,LocalDate targetDate,String priority,int order){super(agency);planId=requiredText(plan,"planId");sourceType=java.util.Objects.requireNonNull(type);sourceId=requiredText(source,"sourceId");if(version<0)throw new IllegalArgumentException("sourceVersion cannot be negative");sourceVersion=version;sourceFingerprint=requiredText(fingerprint,"sourceFingerprint");this.employeeNo=optionalText(employeeNo);if(organizationId==null||organizationId<1)throw new IllegalArgumentException("organizationId is required");this.organizationId=organizationId;this.organizationName=requiredText(organizationName,"organizationName");developmentObjective=requiredText(objective,"developmentObjective");successMeasure=requiredText(measure,"successMeasure");this.targetDate=targetDate;this.priority=requiredText(priority,"priority");if(order<1)throw new IllegalArgumentException("displayOrder must be positive");displayOrder=order;}
 public String getPlanId(){return planId;}public SourceType getSourceType(){return sourceType;}public String getSourceId(){return sourceId;}public long getSourceVersion(){return sourceVersion;}public String getSourceFingerprint(){return sourceFingerprint;}public String getEmployeeNo(){return employeeNo;}public Long getOrganizationId(){return organizationId;}public String getOrganizationName(){return organizationName;}public String getDevelopmentObjective(){return developmentObjective;}public String getSuccessMeasure(){return successMeasure;}public LocalDate getTargetDate(){return targetDate;}public String getPriority(){return priority;}public int getDisplayOrder(){return displayOrder;}
}
